import React, { useState, useEffect } from 'react';

export default function App() {
  const [activeTab, setActiveTab] = useState('marketplace');
  const [listings, setListings] = useState([]);

  // Fetch listings from live backend API on load
  useEffect(() => {
    fetch('http://localhost:5000/api/listings')
      .then(res => res.json())
      .then(data => {
        if (Array.isArray(data)) setListings(data);
      })
      .catch(err => console.log('Backend fetch error:', err));
  }, []);

  const [formData, setFormData] = useState({
    title: '', 
    category: 'Smartphones', 
    brand: 'Apple', 
    modelName: 'iPhone 13',
    condition: 'Good', 
    age: 1, 
    actionType: 'Sell', 
    imageUrl: 'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?auto=format&fit=crop&w=600&q=80'
  });

  const [estValue, setEstValue] = useState(0);
  const [filters, setFilters] = useState({ category: 'All', condition: 'All', action: 'All' });
  const [userCoins, setUserCoins] = useState(700);
  const [selectedListing, setSelectedListing] = useState(null);
  const [certData, setCertData] = useState({ deviceName: '', serialNo: '', method: 'NIST SP 800-88 Purge', verifiedBy: 'EcoSanitize AI Core' });
  const [certGenerated, setCertGenerated] = useState(false);

  // Advanced Category & Brand-Wise Valuation Formula for Viva/Q&A
  useEffect(() => {
    let base = 15000;

    // 1. Category Base Price
    if (formData.category === 'Smartphones') base = 18000;
    else if (formData.category === 'Laptops') base = 35000;
    else if (formData.category === 'Televisions') base = 12000;

    // 2. Brand / Company Multiplier (Apple holds higher resale value than others)
    let brandMultiplier = 1.0;
    if (formData.brand === 'Apple') brandMultiplier = 1.5;      // Premium holding power
    else if (formData.brand === 'Samsung') brandMultiplier = 1.2; // Flagship retain value
    else if (formData.brand === 'OnePlus') brandMultiplier = 1.1; 
    else brandMultiplier = 0.8; // Budget brands like Redmi, Realme, etc.

    // 3. Condition Percentage Weight
    let conditionFactor = 0.7;
    if (formData.condition === 'Like New') conditionFactor = 0.9;
    else if (formData.condition === 'Good') conditionFactor = 0.7;
    else if (formData.condition === 'Fair') conditionFactor = 0.4;
    else conditionFactor = 0.2;

    // 4. Age Depreciation (₹1500 per year drop)
    const ageDeduction = formData.age * 1500;

    // Final Formula Calculation
    const calculatedVal = Math.round((base * brandMultiplier * conditionFactor) - ageDeduction);
    setEstValue(Math.max(500, calculatedVal));
  }, [formData]);

  const handlePostAd = async (e) => {
    e.preventDefault();
    const coins = formData.actionType === 'Recycle' ? 250 : formData.actionType === 'Donate' ? 300 : 150;
    const newAd = {
      ...formData,
      title: `${formData.brand} ${formData.modelName || formData.title}`,
      estimatedValue: estValue,
      status: 'Sorted',
      greenCoins: coins
    };

    try {
      const response = await fetch('http://localhost:5000/api/listings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newAd)
      });
      const savedListing = await response.json();
      setListings([savedListing, ...listings]);
      setUserCoins(prev => prev + coins);
      alert(`Ad Posted & Saved to Cloud Database! Earned +${coins} GreenCoins.`);
      setActiveTab('marketplace');
    } catch (err) {
      alert('Error saving listing to backend.');
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 flex flex-col font-sans">
      <header className="bg-emerald-800 text-white shadow-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 py-3 flex flex-wrap justify-between items-center gap-4">
          <div className="flex items-center space-x-3">
            <div className="bg-amber-400 text-emerald-950 p-2 rounded-xl font-black text-xl tracking-wider shadow-inner">RX</div>
            <div>
              <h1 className="text-xl font-bold tracking-tight">ReCircuit X</h1>
              <p className="text-xs text-emerald-200">Smart Circular E-Waste Ecosystem</p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <div className="bg-amber-400/20 border border-amber-300 text-amber-200 px-3 py-1.5 rounded-full text-xs font-semibold flex items-center gap-1.5 shadow-sm">
              <span className="w-2.5 h-2.5 rounded-full bg-amber-400 animate-pulse"></span>
              🪙 {userCoins} GreenCoins
            </div>
            <div className="bg-sky-100 text-sky-800 px-3 py-1.5 rounded-full text-xs font-semibold">
              🌱 42.5 kg CO₂ Saved
            </div>
          </div>
        </div>

        <nav className="bg-emerald-900 px-4 flex gap-2 overflow-x-auto border-t border-emerald-700/50">
          {[
            { id: 'marketplace', label: 'Marketplace Grid' },
            { id: 'post', label: 'Post Ad & Estimate' },
            { id: 'dashboard', label: 'Impact & Dashboard' },
            { id: 'erasure', label: 'Data-Erasure Certificate' }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`px-4 py-2.5 text-sm font-medium transition whitespace-nowrap border-b-2 ${activeTab === tab.id ? 'border-amber-400 text-amber-300 bg-emerald-950/40' : 'border-transparent text-emerald-100 hover:text-white'}`}
            >
              {tab.label}
            </button>
          ))}
        </nav>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 flex-1 w-full">
        {activeTab === 'marketplace' && (
          <div className="space-y-6">
            <div className="bg-white p-4 rounded-2xl shadow-sm border border-emerald-100 flex flex-wrap gap-4 items-center justify-between">
              <h2 className="text-lg font-bold text-emerald-900">E-Waste Marketplace & Action Router</h2>
              <div className="flex flex-wrap gap-3">
                <select className="border border-slate-200 rounded-lg px-3 py-1.5 text-sm bg-slate-50" onChange={e => setFilters({...filters, category: e.target.value})}>
                  <option value="All">All Categories</option>
                  <option value="Smartphones">Smartphones</option>
                  <option value="Laptops">Laptops</option>
                  <option value="Televisions">Televisions</option>
                </select>
                <select className="border border-slate-200 rounded-lg px-3 py-1.5 text-sm bg-slate-50" onChange={e => setFilters({...filters, action: e.target.value})}>
                  <option value="All">All Actions (Sell/Donate/Recycle)</option>
                  <option value="Sell">Sell</option>
                  <option value="Donate">Donate</option>
                  <option value="Recycle">Recycle</option>
                </select>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {listings.filter(l => (filters.category === 'All' || l.category === filters.category) && (filters.action === 'All' || l.actionType === filters.action)).map(item => (
                <div key={item._id || item.id} className="bg-white rounded-2xl shadow-sm border border-emerald-100 overflow-hidden flex flex-col hover:shadow-md transition">
                  <div className="relative h-48 bg-slate-100">
                    <img src={item.imageUrl} alt={item.title} className="w-full h-full object-cover" />
                    <span className="absolute top-3 right-3 bg-amber-400 text-emerald-950 text-xs font-bold px-2.5 py-1 rounded-full shadow">
                      {item.actionType}
                    </span>
                    <span className="absolute bottom-3 left-3 bg-slate-900/70 backdrop-blur text-white text-xs px-2.5 py-1 rounded-full">
                      Status: {item.status}
                    </span>
                  </div>
                  <div className="p-5 flex-1 flex flex-col justify-between space-y-4">
                    <div>
                      <div className="flex justify-between items-start">
                        <h3 className="font-bold text-slate-800 text-lg">{item.title}</h3>
                        <span className="text-emerald-700 font-bold text-lg">₹{item.estimatedValue}</span>
                      </div>
                      <p className="text-xs text-slate-500 mt-1">{item.brand} • {item.condition} • {item.age} yrs old</p>
                    </div>

                    <div className="pt-3 border-t border-slate-100 flex justify-between items-center">
                      <span className="text-xs font-semibold text-amber-600 bg-amber-50 px-2 py-1 rounded">+{item.greenCoins} GreenCoins</span>
                      <button onClick={() => setSelectedListing(item)} className="bg-emerald-600 text-white px-4 py-2 rounded-xl text-xs font-semibold hover:bg-emerald-700 transition">
                        View & Route Action
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'post' && (
          <div className="max-w-2xl mx-auto bg-white p-8 rounded-2xl shadow-sm border border-emerald-100">
            <h2 className="text-2xl font-bold text-emerald-900 mb-2">Post Device & Estimate Value</h2>
            <p className="text-sm text-slate-500 mb-6">Brand-weighted and condition-based automated pricing calculation engine.</p>

            <form onSubmit={handlePostAd} className="space-y-5">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">Category</label>
                  <select className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm bg-white" onChange={e => setFormData({...formData, category: e.target.value})}>
                    <option value="Smartphones">Smartphones</option>
                    <option value="Laptops">Laptops</option>
                    <option value="Televisions">Televisions</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">Brand / Company</label>
                  <select className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm bg-white" value={formData.brand} onChange={e => setFormData({...formData, brand: e.target.value})}>
                    <option value="Apple">Apple (High Retention)</option>
                    <option value="Samsung">Samsung (Flagship)</option>
                    <option value="OnePlus">OnePlus</option>
                    <option value="Dell">Dell / HP</option>
                    <option value="Other">Other Brands</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">Model Name</label>
                <input type="text" required placeholder="e.g. iPhone 14 Pro / Galaxy S22" className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm" onChange={e => setFormData({...formData, modelName: e.target.value})} />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">Condition</label>
                  <select className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm bg-white" onChange={e => setFormData({...formData, condition: e.target.value})}>
                    <option value="Good">Good (70% Value)</option>
                    <option value="Like New">Like New (90% Value)</option>
                    <option value="Fair">Fair (40% Value)</option>
                    <option value="Non-Working">Non-Working (20% Value)</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">Action Type</label>
                  <select className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm bg-white" onChange={e => setFormData({...formData, actionType: e.target.value})}>
                    <option value="Sell">Sell (Marketplace)</option>
                    <option value="Donate">Donate (NGO Hub)</option>
                    <option value="Recycle">Recycle (Certified Recycler)</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">Device Age: {formData.age} Years (Deducts ₹1500/yr)</label>
                <input type="range" min="0" max="10" value={formData.age} className="w-full accent-emerald-600" onChange={e => setFormData({...formData, age: Number(e.target.value)})} />
              </div>

              {/* Dynamic Valuation Box */}
              <div className="bg-sky-50 border border-sky-200 p-4 rounded-xl flex items-center justify-between">
                <div>
                  <h4 className="text-xs font-bold text-sky-800 uppercase tracking-wide">Brand & Condition Weighted Engine</h4>
                  <p className="text-sm text-sky-900 font-medium">Estimated Residual Value</p>
                </div>
                <div className="text-2xl font-black text-emerald-700">₹{estValue}</div>
              </div>

              <button type="submit" className="w-full bg-emerald-600 text-white py-3 rounded-xl font-semibold hover:bg-emerald-700 transition shadow-sm">
                Publish Listing to Cloud Database
              </button>
            </form>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-emerald-100 flex items-center gap-4">
                <div className="p-4 bg-amber-100 text-amber-700 rounded-2xl text-2xl font-bold">🪙</div>
                <div>
                  <p className="text-xs text-slate-500 font-semibold uppercase">GreenCoins Balance</p>
                  <h3 className="text-2xl font-black text-slate-800">{userCoins}</h3>
                </div>
              </div>
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-emerald-100 flex items-center gap-4">
                <div className="p-4 bg-emerald-100 text-emerald-700 rounded-2xl text-2xl font-bold">🌱</div>
                <div>
                  <p className="text-xs text-slate-500 font-semibold uppercase">CO₂ Footprint Reduced</p>
                  <h3 className="text-2xl font-black text-slate-800">42.5 kg</h3>
                </div>
              </div>
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-emerald-100 flex items-center gap-4">
                <div className="p-4 bg-sky-100 text-sky-700 rounded-2xl text-2xl font-bold">♻️</div>
                <div>
                  <p className="text-xs text-slate-500 font-semibold uppercase">Devices Recycled</p>
                  <h3 className="text-2xl font-black text-slate-800">3 Units</h3>
                </div>
              </div>
            </div>

            <div className="bg-white p-6 rounded-2xl shadow-sm border border-emerald-100">
              <h3 className="text-lg font-bold text-emerald-900 mb-4">GreenCoins Reward Marketplace</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {[
                  { title: '₹250 Amazon Voucher', cost: 500, desc: 'Redeem for e-commerce discount' },
                  { title: 'Plant a Tree in Your Name', cost: 300, desc: 'Verified afforestation initiative' },
                  { title: 'Free Eco-Bag & Kit', cost: 200, desc: 'Recycled cotton tote bag' }
                ].map((reward, i) => (
                  <div key={i} className="border border-slate-100 p-4 rounded-xl bg-slate-50 flex flex-col justify-between">
                    <div>
                      <h4 className="font-bold text-slate-800">{reward.title}</h4>
                      <p className="text-xs text-slate-500 mt-1">{reward.desc}</p>
                    </div>
                    <div className="mt-4 flex items-center justify-between">
                      <span className="text-xs font-bold text-amber-600">🪙 {reward.cost} Coins</span>
                      <button onClick={() => {
                        if(userCoins >= reward.cost) {
                          setUserCoins(userCoins - reward.cost);
                          alert(`Successfully redeemed: ${reward.title}!`);
                        } else {
                          alert('Insufficient GreenCoins!');
                        }
                      }} className="bg-emerald-600 text-white px-3 py-1.5 rounded-lg text-xs font-semibold hover:bg-emerald-700">Redeem</button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'erasure' && (
          <div className="max-w-2xl mx-auto bg-white p-8 rounded-2xl shadow-sm border border-emerald-100 space-y-6">
            <div>
              <h2 className="text-2xl font-bold text-emerald-900">Data-Erasure Certificate Generator</h2>
              <p className="text-sm text-slate-500 mt-1">NIST SP 800-88 compliant digital wiping certificate generator for secure electronics disposal.</p>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">Device Name / Model</label>
                <input type="text" placeholder="e.g. MacBook Pro M1 2020" className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm" onChange={e => setCertData({...certData, deviceName: e.target.value})} />
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">Serial Number / IMEI</label>
                <input type="text" placeholder="e.g. C02G80XYZ940" className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm" onChange={e => setCertData({...certData, serialNo: e.target.value})} />
              </div>

              <div className="p-4 bg-emerald-50 rounded-xl border border-emerald-200 space-y-2">
                <h4 className="font-bold text-emerald-900 text-sm">Security Verification Checklist</h4>
                <div className="text-xs text-emerald-800 space-y-1">
                  <p>✅ Factory Reset Executed & Storage Overwritten</p>
                  <p>✅ Cryptographic Erasure Verified</p>
                  <p>✅ SIM & Cloud Accounts Unlinked</p>
                </div>
              </div>

              <button onClick={() => setCertGenerated(true)} className="w-full bg-emerald-600 text-white py-3 rounded-xl font-semibold hover:bg-emerald-700 transition">
                Generate Verified Certificate PDF
              </button>

              {certGenerated && (
                <div className="p-6 bg-slate-900 text-white rounded-2xl shadow-lg space-y-4 border-2 border-amber-400">
                  <div className="flex justify-between items-center border-b border-slate-700 pb-3">
                    <div>
                      <h3 className="font-black text-amber-400 text-lg">RE-CIRCUIT X CERTIFICATE</h3>
                      <p className="text-xs text-slate-400">Official Data Sanitation Record</p>
                    </div>
                    <span className="bg-emerald-500 text-slate-950 font-bold px-3 py-1 rounded text-xs">VERIFIED</span>
                  </div>
                  <div className="grid grid-cols-2 gap-4 text-xs">
                    <div><span className="text-slate-400">Device:</span> <span className="font-semibold">{certData.deviceName || 'Sample Device'}</span></div>
                    <div><span className="text-slate-400">Serial No:</span> <span className="font-semibold">{certData.serialNo || 'SN-9982341'}</span></div>
                    <div><span className="text-slate-400">Method:</span> <span className="font-semibold">{certData.method}</span></div>
                    <div><span className="text-slate-400">Date:</span> <span className="font-semibold">{new Date().toLocaleDateString()}</span></div>
                  </div>
                  <button onClick={() => window.print()} className="w-full bg-amber-400 text-slate-950 py-2 rounded-lg font-bold text-xs hover:bg-amber-300">
                    Download / Print PDF Certificate
                  </button>
                </div>
              )}
            </div>
          </div>
        )}
      </main>

      {selectedListing && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-3xl max-w-lg w-full p-6 space-y-6 shadow-2xl border border-emerald-100">
            <div className="flex justify-between items-center border-b pb-4">
              <h3 className="font-bold text-lg text-emerald-900">Action Route: {selectedListing.actionType}</h3>
              <button onClick={() => setSelectedListing(null)} className="text-slate-400 hover:text-slate-600 font-bold">✕</button>
            </div>

            <div className="space-y-4">
              <div className="flex gap-4 items-center bg-slate-50 p-3 rounded-xl">
                <img src={selectedListing.imageUrl} alt="" className="w-16 h-16 object-cover rounded-lg" />
                <div>
                  <h4 className="font-bold text-slate-800">{selectedListing.title}</h4>
                  <p className="text-xs text-slate-500">Value: ₹{selectedListing.estimatedValue} • Status: <span className="font-semibold text-emerald-700">{selectedListing.status}</span></p>
                </div>
              </div>

              {selectedListing.actionType === 'Sell' && (
                <div className="bg-emerald-50 p-4 rounded-xl text-xs space-y-2 text-emerald-900">
                  <p className="font-bold">🛍️ Buyer Connection Flow</p>
                  <p>Interested buyers can contact you directly via secure relay email or WhatsApp.</p>
                  <button onClick={() => alert('Contact request sent to registered buyer pool!')} className="w-full bg-emerald-600 text-white py-2 rounded-lg font-semibold mt-2">Reveal Buyer Contact</button>
                </div>
              )}

              {selectedListing.actionType === 'Donate' && (
                <div className="bg-amber-50 p-4 rounded-xl text-xs space-y-2 text-amber-900">
                  <p className="font-bold">🤝 Partner NGO Drop-off</p>
                  <p>Assigned NGO: <span className="font-semibold">Vidya Rural Education Foundation</span></p>
                  <button onClick={() => alert('Pickup scheduled with NGO partner!')} className="w-full bg-amber-600 text-white py-2 rounded-lg font-semibold mt-2">Request Free NGO Pickup</button>
                </div>
              )}

              {selectedListing.actionType === 'Recycle' && (
                <div className="bg-sky-50 p-4 rounded-xl text-xs space-y-2 text-sky-900">
                  <p className="font-bold">♻️ Certified Recycler Pickup</p>
                  <p>Assigned Facility: <span className="font-semibold">EcoRecycle India Tech Park</span></p>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
